'use strict';

// VARIABLES //

var EXPECTED_LINES = [
	'#/',
	'# @license Apache-2.0',
	'#',
	'# Copyright (c) ',
	'#',
	'# Licensed under the Apache License, Version 2.0 (the "License");',
	'# you may not use this file except in compliance with the License.',
	'# You may obtain a copy of the License at',
	'#',
	'#    http://www.apache.org/licenses/LICENSE-2.0',
	'#',
	'# Unless required by applicable law or agreed to in writing, software',
	'# distributed under the License is distributed on an "AS IS" BASIS,',
	'# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.',
	'# See the License for the specific language governing permissions and',
	'# limitations under the License.',
	'#/'
];

var rule;


// FUNCTIONS //

/**
* Rule for validating that YAML files start with the Apache-2.0 license header.
*
* @param {Object} context - ESLint context
* @returns {Object} validators
*/
function main( context ) {
	/**
	* Validates the license header at the start of the YAML file.
	*
	* @private
	* @param {ASTNode} node - program node
	*/
	function validate( node ) {
		var lines;
		var text;
		var line;
		var i;

		text = context.sourceCode.getText( node );
		lines = text.split( '\n' );

		// Must have at least as many lines as the expected header:
		if ( lines.length < EXPECTED_LINES.length ) {
			context.report({
				'node': node,
				'message': 'YAML files must start with the Apache-2.0 license header.',
				'loc': {
					'start': {
						'line': 1,
						'column': 0
					},
					'end': {
						'line': 1,
						'column': 0
					}
				}
			});
			return;
		}
		for ( i = 0; i < EXPECTED_LINES.length; i++ ) {
			line = lines[ i ];

			// Line 3 (index 3) contains the copyright year which varies:
			if ( i === 3 ) {
				if ( line.indexOf( EXPECTED_LINES[ i ] ) !== 0 ) {
					context.report({
						'node': node,
						'message': 'Missing or malformed copyright line in license header.',
						'loc': {
							'start': {
								'line': i + 1,
								'column': 0
							},
							'end': {
								'line': i + 1,
								'column': line.length
							}
						}
					});
					return;
				}
			} else if ( line !== EXPECTED_LINES[ i ] ) {
				context.report({
					'node': node,
					'message': 'YAML files must start with the Apache-2.0 license header. Expected "' + EXPECTED_LINES[ i ] + '" on line ' + ( i + 1 ) + '.',
					'loc': {
						'start': {
							'line': i + 1,
							'column': 0
						},
						'end': {
							'line': i + 1,
							'column': line.length
						}
					}
				});
				return;
			}
		}
	}

	return {
		'Program': validate
	};
}


// MAIN //

rule = {
	'meta': {
		'docs': {
			'description': 'enforce Apache-2.0 license header at the start of YAML files'
		},
		'schema': [],
		'type': 'suggestion'
	},
	'create': main
};


// EXPORTS //

module.exports = rule;
